class SnapshotMapping(object):
    def __init__(self, ):
        # self.sw_version = 'SBTS22R2_ENB_0000_000005_000000'
        # output_file = 'SBTS00_ENB_9999_220107_000001'
        # sw_version = '0.200.3515'
        self.column_list = ['file container', 'filename', 'deployment', 'mandatory flag', 'deployable unit']
        # self.node_id = 1
        # self.mandatory_value = 1

    def verify_mandatory_files_in_snapshot_file(self, **kwargs):
        """
        Verify all mandatory file from SBTS**_trbl_log.list file against snapshot_analysis_file.json

        :param kwargs:
            captured_snapshot_path: Path of the captured snapshot directory or Output from "Collect Snapshot" keyword
                                    can also be given.
            sw_version: software version to fetch snapshot documentation.
            mandatory_flag: If this is set to 1, log files corresponding to 0 will be excluded and will not be
                            verified against snapshot_file_list.
            snapshot_analysis_file: File name where analysis profile is declared.
            snapshot_analysis_profile: snapshot profile declaring other required parameters to match the logfile
                                       against snapshot_file_list
        :return: None

        """
        path_to_captured_snapshot = kwargs['captured_snapshot_path']
        sw_version = kwargs['sw_version']
        mandatory_value = kwargs.pop('mandatory_flag', 1)
        snapshot_analysis_file = kwargs.pop('snapshot_analysis_file', 'snapshot_analysis_file.json')
        analysis_profile = kwargs.pop('snapshot_analysis_profile', 'analysis_profile')
        bts_id = get_config_variable(['testline'])

        file_name_list, deployable_unit = self.read_snapshot_analysis_profile(snapshot_analysis_file,
                                                                              analysis_profile, **kwargs)

        output_file = 'execution_logs/{}_snapshot_documentation'.format(sw_version)
        output_dir = '{}'.format(output_file)
        logger.debug("Downloading snapshot documentation for sw version {}".format(sw_version))
        doc_path = self.download_snapshot_document(sw_version, output_file)
        logger.debug("Snapshot documentation downloaded successfully to path {}".format(doc_path))
        unpacked_file_path = self.unpack_document(doc_path, output_dir)
        logger.debug("Unpacked snapshot documentation into path {}".format(unpacked_file_path))
        file_content = self.fetch_content_from_trbl_log_list_csv(unpacked_file_path, sw_version, self.column_list)
        logger.debug("Content of trbl log file is {}".format(file_content))
        file_list_to_verify = self.collect_specified_files_from_trbl_csv(file_content, file_name_list, mandatory_value)
        mapped_filename = self.map_deployment_column_with_deployable_unit(file_list_to_verify, deployable_unit, bts_id)
        logger.debug("File names to be verifed in snapshot txt are :: {}".format(mapped_filename))
        self.verify_file_in_snapshot_file(path_to_captured_snapshot, mapped_filename)
        self.verify_if_file_exist(mapped_filename)

    def read_snapshot_analysis_profile(self, snapshot_analysis_file, analysis_profile, **kwargs):
        """
        Read all declared attributes from snapshot analysis profile file

        :param snapshot_analysis_file: File name where analysis profile is declared.
        :param analysis_profile: snapshot profile declaring other required parameters to match the logfile against
                                 snapshot_file_list
        :param kwargs:
            file_names_to_match: If not give from testcase, this parameter wil be fetched from snapshot_analysis_file.
            deployable_unit: If not give from testcase, this parameter wil be fetched from snapshot_analysis_file.

        :return: Tuple of all declared attributes
                 (file_name_list, deployable_unit)
        """
        snapshot_analysis_file = resource_file.load_json_file(snapshot_analysis_file)
        profile_detail = snapshot_analysis_file['snapshot_analysis_profile'].get(analysis_profile)
        file_name_list = kwargs.get('file_names_to_match', profile_detail['file_names_to_match'])
        deployable_unit = kwargs.pop('deployable_unit', profile_detail['deployable_unit'])
        return file_name_list, deployable_unit

    def download_pdd_file(self, **kwargs):
        """
        Downloads pdd file specific to the given component

        :param kwargs:
            sw_version : Mandatory, Build name to download pdd file from snapshot document
            component : Mandatory, Name of teh component tyo fetch valid PDD file per component
            download_path : optional, Path to download pdd files

        *Returns:*\n
             Path to downloaded pdd file directory
        """
        sw_version = kwargs["sw_version"]
        component = kwargs["component"]
        pdd_dir = kwargs.get("download_path", "execution_logs/pdd_dir/")
        output_file = "execution_logs/temp_snapshot_doc"
        temp_snapdoc_dir = "execution_logs/temp_snapshot_doc_dir/"
        snap_doc_path = ""

        pdds_path_map = pdd_mapping.get_path_to_component_pdds(component)

        try:
            snap_doc_path = self.download_snapshot_document(sw_version=sw_version, output_file=output_file)
            self.unpack_document(snap_doc_path, temp_snapdoc_dir)
            for pdd_file, pdd_path in pdds_path_map.items():
                src = temp_snapdoc_dir + "" + pdd_path + "/" + pdd_file
                self._copy_pdd_files(src, pdd_dir)
        except Exception as e:
            raise Exception(e)
        finally:
            fd_list = [snap_doc_path, temp_snapdoc_dir]
            self._remove_collected_documents(fd_list)
            return os.path.abspath(pdd_dir)

    def download_snapshot_document(self, sw_version, output_file):
        """
        Downloads snapshot documentation of the given software version

        :param sw_version: software version to fetch snapshot documentation.
        :param output_file: File name where downloaded documentation zip to be made available.

        :return: str, Downloaded path
        """
        # Download snapshot documentation of given build
        if sw_version.find("ENB") != -1:
            sw_version = sw_version.replace(".", "_")
            http = "http://files.ute.nsn-rdnet.net/builds/enb/base/{0}/{0}_snapshot_documentation.tgz" \
                .format(sw_version)
        else:
            http = "https://artifactory-hz1.int.net.nokia.com/artifactory/mnp5g-central-public-remote/System_Release" \
                   "/{0}/snapshot_documentation-{0}.tgz".format(sw_version)
        req = requests.get(http)

        if req.status_code == 200:
            with open(output_file + ".tgz", "wb") as f:
                f.write(req.content)
            docu_path = os.path.abspath(output_file + ".tgz")
        else:
            raise IOError("Snapshot documentation not found: " + http)
        return docu_path

    def unpack_document(self, docu_path, output_dir):
        """
        Unpack given document to the specified output directory

        :param docu_path: Path to the directory to be unpacked
        :param output_dir: Name to be given for the unpacked directory

        :return: str, path where unzipped folder is kept
        """
        call(["gunzip", "-f", docu_path], stdout=open(os.devnull, 'w'))
        docu_tar = docu_path.replace(".tgz", ".tar")
        call(["7za", "x", docu_tar, "-y", "-o" + output_dir], stdout=open(os.devnull, 'w'))
        # call(["rm", "-f", docu_tar], stdout=open(os.devnull, 'w'))
        self._remove_collected_documents([docu_tar])
        final_path = os.path.abspath(output_dir)
        return final_path

    def fetch_content_from_trbl_log_list_csv(self, file_path, sw_version, column_list):
        """
        Fetch all content from SBTS***_trbl_log_list file

        :param file_path: Path to SBTS**_trbl_log_list.csv file.
        :param sw_version: software version to match the exact SBTS****_trbl_log_list.csv file.
        :param column_list: List of columns to be fetched from the csv file

        :return: DataFrame or TextParser
        """
        # Collect content of buildNum_trbl_log_list.csv from downloaded snapshot documentation
        csv_file_path = '{}/{}_trbl_log_list.csv'.format(file_path, sw_version)
        content = pd.read_csv(csv_file_path, sep=';', usecols=column_list)
        return content

    def collect_specified_files_from_trbl_csv(self, content, file_name_list, mandatory_value):
        """
        Collect all files names specified in file_name_list from trbl_log_list csv file

        :param content: Content given trbl_log_list csv file
        :param file_name_list: Filenames to be picked from trbl_log_list to match against snapshot_file_list
        :param mandatory_value: Filename corresponding to given mandatory value will be included to verify against
                                snapshot_file_list

        :return: [list[list]], [[file_content, file_name, deployment, mandatory_flag, deployable_unit],
                   [file_content, file_name, deployment, mandatory_flag, deployable_unit]]
        """
        # Collect user given filename with specified extension
        filename_to_be_verified = []
        excluded_files = []
        included_files = []
        for item in content.values:
            file_content, file_name, deployment, mandatory_flag, deployable_unit = item
            if not pd.isna(file_content):
                for name in file_name_list:
                    # resp = re.findall('((.*){}(.*)(gz|zip))'.format(name), file_content)
                    resp = re.findall('((.*){})'.format(name), file_content)
                    if resp:
                        # Filter files to be verified against Mandatory flag
                        if int(item[3]) == int(mandatory_value):
                            filename_to_be_verified.append([resp[0][0], file_name, deployment, mandatory_flag,
                                                            deployable_unit])
                            included_files.append(resp[0][0])
                        else:
                            excluded_files.append(resp[0][0])
        logger.debug("files to be verified {}".format(filename_to_be_verified))
        return filename_to_be_verified

    def map_deployment_column_with_deployable_unit(self, filename_to_be_verified, deployable_unit, bts_id):
        """
        Map deployment column against deployable unit

        :param filename_to_be_verified: Output from collect_specified_files_from_trbl_csv
        :param deployable_unit: Deployable unit to be mapped to corresponding file container of the given filename
        :param bts_id: BTS id to be mapped to corresponding file container of the given filename

        :return: list, list of file names picked to verify against snapshot_file_list.txt
        """
        # Map the deployment column with deployable unit
        # ALL_DSP_CORES,
        print("Done")
        mapped_files = {}
        for item in filename_to_be_verified:
            # container_file, others, deployable_unit_from_file = item
            container_file, *others, deployable_unit_from_file = item
            node_list = self._get_node_list(deployable_unit_from_file, deployable_unit)
            for node in node_list:
                if re.search('^1', node):
                    if 'BTSID' in item[0]:
                        mapped_files['BTS{}_'.format(bts_id) + container_file.replace('__BTSID__NODE_ID', node)] = \
                            mapped_files.get('BTS{}_'.format(bts_id) + container_file.replace('__BTSID__NODE_ID', node),
                                             0) + 1
                    elif 'NODE_ID' in item[0]:
                        mapped_files['BTS{}'.format(bts_id) + container_file.replace('_NODE_ID__', node)] = \
                            mapped_files.get('BTS{}'.format(bts_id) + container_file.replace('_NODE_ID__', node), 0) + 1
                    else:
                        mapped_files['BTS{}_'.format(bts_id) + node + '_' + container_file.replace('*_', '')] = \
                            mapped_files.get('BTS{}_'.format(bts_id) + node + '_' + container_file.replace('*_', ''),
                                             0) + 1
        logger.debug("verify filename {} in snapshot.txt file".format(mapped_files))
        return mapped_files

    def verify_file_in_snapshot_file(self, path_to_captured_snapshot, filenames_to_verify):
        """
        Verify all identified files from SBTS***_trbl_log_list file against snapshot_file_list.txt

        :param path_to_captured_snapshot: Path of the captured snapshot directory
        :param filenames_to_verify: Output from map_deployment_column_with_deployable_unit

        :return: None
        """
        # Verify mapped_filename against snapshot_file.txt
        output_path = 'execution_logs/captured_snapshot_unpacked'
        logger.debug("unzipping captured snapshot folder")
        self.unpack_document(path_to_captured_snapshot, output_path)
        logger.debug("Successfully unzipped captured snapshot folder to {}".format(output_path))
        output = self.get_snapshot_file_content()
        for file in filenames_to_verify:
            if file in output:
                logger.debug("file {} present in captured snapshot".format(file))
            else:
                logger.debug("file {} is not present in captured snapshot".format(file))

    def get_snapshot_file_content(self):
        output_path = 'execution_logs/captured_snapshot_unpacked'
        with open('{}/snapshot_file_list.txt'.format(output_path), 'r') as captured_snap:
            captured_content = captured_snap.readlines()
            output = [cap_con.replace("\n", "").strip() for cap_con in captured_content]
        return output

    def verify_if_file_exist(self, filenames_to_verify):
        logger.debug("Check if file exist")
        output = self.get_snapshot_file_content()
        partition_dict = self.get_partition_files_from_snapshot(output)
        for each_part in partition_dict:
            for file in filenames_to_verify:
                if file in partition_dict[each_part]:
                    logger.debug("file {} present in captured snapshot".format(file))
                else:
                    logger.debug("file {} is not present in captured snapshot".format(file))

    def get_partition_files_from_snapshot(self, snapshot_file_list, bts_id=get_config_variable(['testline'])):
        output = snapshot_file_list
        partition_wise_dict = {}
        partitions_index_list = []
        i = 0
        for m in re.finditer("BTS{}_\w*_part_\d*.zip:".format(bts_id), str(output)):
            partition_wise_dict[str(output)[m.start():m.end()]] = output.index(str(output)[m.start():m.end()])
            partitions_index_list.append(output.index(str(output)[m.start():m.end()]))
        for key in partition_wise_dict:
            if (i + 1) < len(partitions_index_list):
                partition_wise_dict[key] = output[partitions_index_list[i]:partitions_index_list[i + 1]]
            else:
                partition_wise_dict[key] = output[partitions_index_list[i]:]
            i += 1
        return partition_wise_dict


    def _get_node_list(self, item, deployable_unit):
        item_list = item.split(",")
        node_list = []
        for each_item in item_list:
            ss = node_list.append(each_item.replace('0x', '')) if each_item in deployable_unit else ''
        return node_list

    def _ignore_if_present(self, content, value_to_check):
        if value_to_check in content:
            return True, 1
        return False, 0

    def _remove_collected_documents(self, file_list):
        for f in file_list:
            call(["rm", "-rf", f])

    def _copy_pdd_files(self, source, dest):
        # if not os.path.exists(dest):
        #     os.mkdir(dest)
        call(["cp", source, dest])
